import { useState, useEffect, useRef } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Download, RefreshCw, Crown, Brain, Zap, Infinity, Mail } from "lucide-react";
import { useLocation } from "wouter";
import type { DogPortrait } from "@shared/schema";
import GoogleAdSense from "@/components/GoogleAdSense";

type DogPortraitWithDemo = DogPortrait & { isDemo?: boolean };

const breeds = [
  { value: "random", label: "Random Breed" },
  { value: "golden-retriever", label: "Golden Retriever" },
  { value: "labrador", label: "Labrador" },
  { value: "german-shepherd", label: "German Shepherd" },
  { value: "bulldog", label: "Bulldog" },
  { value: "poodle", label: "Poodle" },
  { value: "beagle", label: "Beagle" },
  { value: "rottweiler", label: "Rottweiler" },
  { value: "yorkshire-terrier", label: "Yorkshire Terrier" },
  { value: "dachshund", label: "Dachshund" },
  { value: "siberian-husky", label: "Siberian Husky" },
  { value: "bernese-mountain-dog", label: "Bernese Mountain Dog" },
  { value: "st-bernard", label: "St. Bernard" },
];

const colors = [
  { value: "", label: "Natural Color" },
  { value: "golden", label: "Golden" },
  { value: "brown", label: "Brown" },
  { value: "black", label: "Black" },
  { value: "white", label: "White" },
  { value: "cream", label: "Cream" },
  { value: "red", label: "Red" },
  { value: "silver", label: "Silver" },
];

const backgrounds = [
  { value: "", label: "Default Park" },
  { value: "a sunny beach with waves and sand", label: "Beach Scene" },
  { value: "a snowy mountain landscape", label: "Mountain Snow" },
  { value: "a colorful flower garden", label: "Flower Garden" },
  { value: "a forest with tall trees", label: "Forest" },
  { value: "a modern city park", label: "City Park" },
  { value: "a countryside meadow", label: "Meadow" },
  { value: "a cozy living room", label: "Indoor Living Room" },
];

export default function Home() {
  const [selectedBreed, setSelectedBreed] = useState("random");
  const [selectedColor, setSelectedColor] = useState("");
  const [selectedBackground, setSelectedBackground] = useState("");
  const [isPremium, setIsPremium] = useState(false);
  const [currentPortrait, setCurrentPortrait] = useState<DogPortraitWithDemo | null>(null);
  const [emailSignup, setEmailSignup] = useState("");
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [, setLocation] = useLocation();
  const { toast } = useToast();

  useEffect(() => {
    const premiumStatus = localStorage.getItem('pupPortraitPremium');
    if (premiumStatus === 'true') {
      setIsPremium(true);
    }

    const urlParams = new URLSearchParams(window.location.search);
    const premiumParam = urlParams.get('premium');

    if (premiumParam === 'success') {
      localStorage.setItem('pupPortraitPremium', 'true');
      setIsPremium(true);
      toast({
        title: "Premium Activated!",
        description: "Welcome to Pup Portrait Premium! You now have unlimited portraits and exclusive features.",
      });
      window.history.replaceState({}, document.title, window.location.pathname);
    } else if (premiumParam === 'cancelled') {
      toast({
        title: "Payment Cancelled",
        description: "No worries! You can upgrade to premium anytime.",
        variant: "destructive",
      });
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  const generatePortraitMutation = useMutation({
    mutationFn: async (params: { breed: string; color?: string; background?: string }) => {
      const response = await apiRequest("POST", "/api/generate-portrait", params);
      return response.json();
    },
    onSuccess: (data: DogPortraitWithDemo) => {
      setIsTransitioning(false);
      setCurrentPortrait(data);
      toast({
        title: data.isDemo ? "Demo Portrait Loaded!" : "Portrait Generated!",
        description: data.isDemo 
          ? `Meet ${data.name}! Add OpenAI credits for AI-generated portraits.`
          : `Meet ${data.name}, a beautiful ${data.breed}`,
      });
    },
    onError: (error) => {
      setIsTransitioning(false);
      toast({
        title: "Generation Failed",
        description: "Failed to generate portrait. Please try again.",
        variant: "destructive",
      });
    },
  });

  const emailSignupMutation = useMutation({
    mutationFn: async (email: string) => {
      const response = await apiRequest("POST", "/api/email-signup", { email });
      return response.json();
    },
    onSuccess: (data) => {
      setEmailSignup("");
      toast({
        title: "Successfully Signed Up!",
        description: "You'll receive daily dog portraits in your email.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Signup Failed",
        description: error.message || "Failed to sign up. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleEmailSignup = () => {
    if (!emailSignup.trim()) {
      toast({
        title: "Email Required",
        description: "Please enter your email address.",
        variant: "destructive",
      });
      return;
    }
    emailSignupMutation.mutate(emailSignup);
  };

  const handleGeneratePortrait = () => {
    const params: { breed: string; color?: string; background?: string } = { 
      breed: selectedBreed 
    };
    if (isPremium && selectedColor) params.color = selectedColor;
    if (isPremium && selectedBackground) params.background = selectedBackground;

    setIsTransitioning(true);
    generatePortraitMutation.mutate(params);
  };

  const handleDownload = async () => {
    if (!currentPortrait) return;

    try {
      const response = await fetch(`/api/proxy-image?url=${encodeURIComponent(currentPortrait.imageUrl)}`);

      if (!response.ok) {
        throw new Error('Failed to fetch image');
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${currentPortrait.name}-${currentPortrait.generationId}.jpg`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);

      toast({
        title: "Download Started",
        description: "Your portrait is being downloaded",
      });
    } catch (error) {
      console.error('Download error:', error);
      try {
        window.open(currentPortrait.imageUrl, '_blank');
        toast({
          title: "Image Opened",
          description: "Right-click the image to save it to your device",
        });
      } catch (fallbackError) {
        toast({
          title: "Download Failed",
          description: "Please right-click the image and select 'Save image as...'",
          variant: "destructive",
        });
      }
    }
  };

  const handlePremiumUpgrade = async () => {
    if (isPremium) return;

    try {
      const response = await apiRequest("POST", "/api/create-checkout-session");
      const { url } = response;

      window.location.href = url;
    } catch (error: any) {
      toast({
        title: "Payment Error",
        description: error.message || "Could not start checkout process. Please try again.",
        variant: "destructive",
      });
    }
  };

  useEffect(() => {
    if (!currentPortrait) {
      handleGeneratePortrait();
    }
  }, []);

  return (
    <div className="min-h-screen bg-background text-foreground">
      <header className="container mx-auto px-4 py-8 text-center">
        <div className="animate-in fade-in-0 duration-500">
          <h1 className="text-4xl md:text-6xl font-bold bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent mb-6 leading-relaxed pb-4">
            Pup Portrait
          </h1>
          <p className="text-muted-foreground text-lg md:text-xl max-w-2xl mx-auto">
            Create stunning, photorealistic portraits of your dream dog using advanced AI technology
          </p>
        </div>
      </header>

      <GoogleAdSense format="leaderboard" slot="top-leaderboard" />

      <main className="container mx-auto px-4 pb-16">
        <div className="max-w-4xl mx-auto">

          {isPremium && (
            <div className="mb-6 text-center animate-in fade-in-0 duration-500">
              <div className="inline-flex items-center px-4 py-2 bg-gradient-to-r from-amber-500 to-orange-500 text-white rounded-full text-sm font-medium">
                <Crown className="w-4 h-4 mr-2" />
                Premium Active
              </div>
            </div>
          )}

          <div className="mb-8 animate-in fade-in-0 duration-500 delay-100">
            <div className="grid gap-4 max-w-4xl mx-auto">

              <div className="flex flex-col sm:flex-row gap-4 items-center justify-center">
                <label className="text-foreground font-medium min-w-[100px]">Breed:</label>
                <Select value={selectedBreed} onValueChange={setSelectedBreed}>
                  <SelectTrigger className="w-[200px]">
                    <SelectValue placeholder="Choose a breed" />
                  </SelectTrigger>
                  <SelectContent>
                    {breeds.map((breed) => (
                      <SelectItem key={breed.value} value={breed.value}>
                        {breed.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {isPremium && (
                <>
                  <div className="flex flex-col sm:flex-row gap-4 items-center justify-center">
                    <label className="text-foreground font-medium min-w-[100px]">Color:</label>
                    <Select value={selectedColor} onValueChange={setSelectedColor}>
                      <SelectTrigger className="w-[200px]">
                        <SelectValue placeholder="Choose color" />
                      </SelectTrigger>
                      <SelectContent>
                        {colors.map((color) => (
                          <SelectItem key={color.value} value={color.value}>
                            {color.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="flex flex-col sm:flex-row gap-4 items-center justify-center">
                    <label className="text-foreground font-medium min-w-[100px]">Background:</label>
                    <Select value={selectedBackground} onValueChange={setSelectedBackground}>
                      <SelectTrigger className="w-[200px]">
                        <SelectValue placeholder="Choose background" />
                      </SelectTrigger>
                      <SelectContent>
                        {backgrounds.map((bg) => (
                          <SelectItem key={bg.value} value={bg.value}>
                            {bg.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </>
              )}

            </div>
          </div>

          <Card className="portrait-card transition-all duration-300 hover:shadow-2xl hover:-translate-y-1 animate-in fade-in-0 duration-500 delay-200">
            <CardContent className="p-6 md:p-8">

              {generatePortraitMutation.isPending && (
                <div className="text-center">
                  <Skeleton className="aspect-square max-w-md mx-auto rounded-xl mb-6" />
                  <div className="flex items-center justify-center gap-2 text-muted-foreground">
                    <RefreshCw className="w-4 h-4 animate-spin" />
                    <span>Generating your unique dog portrait...</span>
                  </div>
                </div>
              )}

              {currentPortrait && !generatePortraitMutation.isPending && (
                <div className={`transition-all duration-700 ${isTransitioning ? 'opacity-50 scale-95' : 'opacity-100 scale-100'} animate-in fade-in-0 duration-500`}>
                  <div className="relative max-w-md mx-auto mb-6">
                    <img 
                      src={currentPortrait.imageUrl}
                      alt={`AI-generated ${currentPortrait.breed} portrait`}
                      className="w-full aspect-square object-cover rounded-xl shadow-lg transition-all duration-700 hover:scale-105"
                    />

                    <div className="absolute bottom-3 left-3 bg-black/60 backdrop-blur-sm rounded-lg px-3 py-2">
                      <span className="text-xs text-white font-medium">
                        {currentPortrait.breed}
                      </span>
                    </div>

                    {currentPortrait.isDemo && (
                      <div className="absolute top-3 left-3 bg-amber-500/90 backdrop-blur-sm rounded-lg px-3 py-2">
                        <span className="text-xs text-white font-medium">
                          DEMO
                        </span>
                      </div>
                    )}
                  </div>

                  <div className="text-center mb-6">
                    <h3 className="text-xl font-semibold mb-2">
                      Meet {currentPortrait.name}
                    </h3>
                    {currentPortrait.isDemo ? (
                      <div className="space-y-2">
                        <p className="text-muted-foreground text-sm">
                          This is a demo portrait. Add OpenAI credits for AI-generated portraits.
                        </p>
                        <div className="inline-flex items-center px-3 py-1 bg-amber-500/20 text-amber-400 rounded-full text-xs">
                          Demo Mode Active
                        </div>
                      </div>
                    ) : (
                      <p className="text-muted-foreground text-sm">
                        This beautiful dog was created by AI and doesn't exist in real life
                      </p>
                    )}
                  </div>
                </div>
              )}

              {generatePortraitMutation.isError && !generatePortraitMutation.isPending && (
                <div className="text-center py-8">
                  <p className="text-destructive mb-4">
                    Failed to generate portrait. Please try again.
                  </p>
                  <Button onClick={handleGeneratePortrait} variant="outline">
                    Try Again
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>

          {!isPremium && (
            <div className="mt-8 mb-8 animate-in fade-in-0 duration-500 delay-250 flex justify-center">
              <Card className="bg-gradient-to-r from-amber-50 to-orange-50 dark:from-amber-950/20 dark:to-orange-950/20 border-amber-200 dark:border-amber-800 max-w-2xl w-full">
                <CardContent className="p-6">
                  <div className="text-center mb-4">
                    <div className="inline-flex items-center gap-2 mb-2">
                      <Crown className="w-5 h-5 text-amber-600" />
                      <h3 className="text-xl font-bold text-amber-800 dark:text-amber-200">Upgrade to Premium - $9.99</h3>
                    </div>
                    <p className="text-amber-700 dark:text-amber-300 text-sm">Unlock custom colors and scenic backgrounds</p>
                  </div>

                  <div className="grid md:grid-cols-2 gap-4">
                    <div className="space-y-3">
                      <div className="flex items-center gap-2">
                        <Infinity className="w-4 h-4 text-amber-500" />
                        <span className="text-sm font-medium text-amber-800 dark:text-amber-200">Unlimited Portraits</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <Zap className="w-4 h-4 text-amber-500" />
                        <span className="text-sm font-medium text-amber-800 dark:text-amber-200">Priority Processing</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <Brain className="w-4 h-4 text-amber-500" />
                        <span className="text-sm font-medium text-amber-800 dark:text-amber-200">Exclusive AI Models</span>
                      </div>
                    </div>
                    <div className="space-y-3">
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 bg-amber-500 rounded-full" />
                        <span className="text-sm font-medium text-amber-800 dark:text-amber-200">Custom Fur Colors</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 bg-amber-500 rounded-full" />
                        <span className="text-sm font-medium text-amber-800 dark:text-amber-200">Scenic Backgrounds</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <Download className="w-4 h-4 text-amber-500" />
                        <span className="text-sm font-medium text-amber-800 dark:text-amber-200">HD Downloads</span>
                      </div>
                    </div>
                  </div>

                  <div className="mt-6 text-center">
                    <Button 
                      onClick={handlePremiumUpgrade}
                      className="bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-white font-semibold px-8 py-3 flex items-center gap-2 mx-auto"
                    >
                      <Crown className="w-4 h-4" />
                      Upgrade to Premium - $9.99
                    </Button>
                  </div>

                </CardContent>
              </Card>
            </div>
          )}

          <div className="mt-8 flex flex-col sm:flex-row gap-4 justify-center items-center animate-in fade-in-0 duration-500 delay-300">

            <Button 
              onClick={handleGeneratePortrait}
              disabled={generatePortraitMutation.isPending}
              className="bg-primary hover:bg-primary/90 text-primary-foreground font-semibold px-6 py-3 flex items-center gap-2"
            >
              <RefreshCw className={`w-4 h-4 ${generatePortraitMutation.isPending ? 'animate-spin' : ''}`} />
              Generate New Portrait
            </Button>

            <Button 
              onClick={handleDownload}
              disabled={!currentPortrait}
              variant="secondary"
              className="font-semibold px-6 py-3 flex items-center gap-2"
            >
              <Download className="w-4 h-4" />
              Download HD
            </Button>

            {isPremium && (
              <Button 
                disabled
                className="bg-green-600 hover:bg-green-600 text-white font-semibold px-6 py-3 flex items-center gap-2"
              >
                <Crown className="w-4 h-4" />
                Premium Active
              </Button>
            )}
          </div>

          <div className="mt-16 grid md:grid-cols-3 gap-8 animate-in fade-in-0 duration-500 delay-400">
            <Card className="text-center p-6">
              <CardContent className="p-0">
                <div className="w-12 h-12 bg-blue-500/20 rounded-lg flex items-center justify-center mx-auto mb-4">
                  <Brain className="w-6 h-6 text-blue-400" />
                </div>
                <h4 className="font-semibold text-lg mb-2">Advanced AI</h4>
                <p className="text-muted-foreground text-sm">
                  Powered by DALL-E 3 to create your perfect dream dog companion
                </p>
              </CardContent>
            </Card>

            <Card className="text-center p-6">
              <CardContent className="p-0">
                <div className="w-12 h-12 bg-green-500/20 rounded-lg flex items-center justify-center mx-auto mb-4">
                  <Zap className="w-6 h-6 text-green-400" />
                </div>
                <h4 className="font-semibold text-lg mb-2">Lightning Fast</h4>
                <p className="text-muted-foreground text-sm">
                  Generate stunning portraits in seconds with optimized processing
                </p>
              </CardContent>
            </Card>

            <Card className="text-center p-6">
              <CardContent className="p-0">
                <div className="w-12 h-12 bg-purple-500/20 rounded-lg flex items-center justify-center mx-auto mb-4">
                  <Infinity className="w-6 h-6 text-purple-400" />
                </div>
                <h4 className="font-semibold text-lg mb-2">Your Perfect Dog</h4>
                <p className="text-muted-foreground text-sm">
                  Create the exact dog you've always dreamed of having
                </p>
              </CardContent>
            </Card>
          </div>

        </div>

        <div className="mt-16 text-center">
          <Card className="max-w-2xl mx-auto">
            <CardContent className="p-8">
              <div className="mb-6">
                <div className="w-16 h-16 bg-blue-500/20 rounded-lg flex items-center justify-center mx-auto mb-4">
                  <Mail className="w-8 h-8 text-blue-400" />
                </div>
                <h3 className="text-2xl font-bold mb-2">
                  Daily Dog Picture of the Day
                </h3>
                <p className="text-muted-foreground text-lg">
                  Get a beautiful, AI-generated dog portrait delivered to your inbox every day - completely free!
                </p>
              </div>

              <div className="flex flex-col sm:flex-row gap-4 items-center justify-center max-w-md mx-auto">
                <Input
                  type="email"
                  placeholder="Enter your email address"
                  value={emailSignup}
                  onChange={(e) => setEmailSignup(e.target.value)}
                  className="flex-1"
                  disabled={emailSignupMutation.isPending}
                />
                <Button 
                  onClick={handleEmailSignup}
                  disabled={emailSignupMutation.isPending}
                  className="w-full sm:w-auto"
                >
