import React, { useEffect, useRef, useState } from 'react';

interface GoogleAdSenseProps {
  format?: 'banner' | 'rectangle' | 'leaderboard' | 'skyscraper' | 'square';
  size?: string;
  className?: string;
  slot?: string;
}

declare global {
  interface Window {
    adsbygoogle: any[];
  }
}

const GoogleAdSense: React.FC<GoogleAdSenseProps> = ({ 
  format = 'banner', 
  size,
  className = '',
  slot = 'demo-ad-slot'
}) => {
  const publisherId = 'ca-pub-2481111694255269';
  const adRef = useRef<HTMLElement>(null);
  const [adLoaded, setAdLoaded] = useState(false);
  const [showFallback, setShowFallback] = useState(false);

  const getAdDimensions = () => {
    switch (format) {
      case 'leaderboard':
        return { width: '728px', height: '90px', description: 'Leaderboard (728x90)' };
      case 'banner':
        return { width: '320px', height: '50px', description: 'Mobile Banner (320x50)' };
      case 'rectangle':
        return { width: '300px', height: '250px', description: 'Medium Rectangle (300x250)' };
      case 'skyscraper':
        return { width: '160px', height: '600px', description: 'Wide Skyscraper (160x600)' };
      case 'square':
        return { width: '250px', height: '250px', description: 'Square (250x250)' };
      default:
        const w = size?.split('x')[0] || '320';
        const h = size?.split('x')[1] || '50';
        return { width: `${w}px`, height: `${h}px`, description: `Custom (${w}x${h})` };
    }
  };

  const { width, height, description } = getAdDimensions();

  useEffect(() => {
    const fallbackTimer = setTimeout(() => {
      if (!adLoaded) {
        setShowFallback(true);
      }
    }, 3000);

    try {
      if (!window.adsbygoogle) {
        window.adsbygoogle = [];
      }

      const timer = setTimeout(() => {
        if (adRef.current) {
          try {
            window.adsbygoogle.push({});
            setAdLoaded(true);
            console.log('AdSense ad initialized for slot:', slot);
          } catch (error) {
            console.log('AdSense note:', error.message);
            setShowFallback(true);
          }
        }
      }, 100);

      return () => {
        clearTimeout(timer);
        clearTimeout(fallbackTimer);
      };
    } catch (error) {
      console.error('AdSense initialization error:', error);
      setShowFallback(true);
    }
  }, [slot, adLoaded]);

  if (showFallback) {
    return (
      <div className={`flex justify-center my-4 ${className}`}>
        <div 
          style={{ width, height }}
          className="bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-sm relative overflow-hidden"
        >
          <div className="absolute top-1 right-1 text-xs text-gray-400 font-sans">
            AdChoices
          </div>
          <div className="absolute top-1 left-1 text-xs text-gray-400 font-sans">
            Ad
          </div>

          <div className="flex flex-col items-center justify-center h-full p-2 text-center">
            <div className="text-xs text-gray-500 dark:text-gray-400 mb-1 font-sans">
              Advertisement
            </div>
            <div className="text-xs text-gray-400 dark:text-gray-500 font-sans">
              {description}
            </div>
            <div className="text-xs text-gray-300 dark:text-gray-600 mt-1 font-mono">
              google.com/adsense
            </div>
          </div>

          <div className="absolute bottom-1 right-1 text-xs text-blue-600 dark:text-blue-400 font-sans">
