          </div>

          <div className="absolute inset-0 border border-gray-300 dark:border-gray-600 rounded-sm pointer-events-none opacity-50"></div>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex justify-center my-4 ${className}`}>
      <ins 
