import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { insertDogPortraitSchema, insertEmailSignupSchema } from "@shared/schema";
import { z } from "zod";
import OpenAI from "openai";
import Stripe from "stripe";

const openai = new OpenAI({ 
  apiKey: process.env.OPENAI_API_KEY || process.env.OPENAI_API_KEY_ENV_VAR || "default_key" 
});

if (!process.env.STRIPE_SECRET_KEY) {
  throw new Error('Missing required Stripe secret: STRIPE_SECRET_KEY');
}
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY, {
  apiVersion: "2023-10-16",
});

export async function registerRoutes(app: Express): Promise<Server> {
  app.post("/api/generate-portrait", async (req, res) => {
    try {
      const { breed } = req.body;

      if (!breed || typeof breed !== 'string') {
        return res.status(400).json({ message: "Breed is required and must be a string" });
      }

      const dogNames = [
        "Bailey", "Max", "Luna", "Charlie", "Bella", "Cooper", "Lucy", 
        "Buddy", "Sadie", "Rocky", "Molly", "Tucker", "Daisy", "Duke", 
        "Lola", "Bear", "Sophie", "Zeus", "Chloe", "Bentley"
      ];
      const randomName = dogNames[Math.floor(Math.random() * dogNames.length)];

      const { color, background } = req.body;

      const breedText = breed === "random" ? "mixed breed dog" : breed.replace("-", " ");
      const colorText = color ? ` with ${color} colored fur` : "";

      const backgroundSettings = {
        "a sunny beach with waves and sand": "sunny beach with waves and sand",
        "a snowy mountain landscape": "mountain trail with pine trees and rocky terrain", 
        "a colorful flower garden": "suburban backyard with green lawn and wooden fence",
        "a forest with tall trees": "forest clearing with dappled sunlight through trees",
        "a modern city park": "park setting with large oak trees and walking path",
        "a countryside meadow": "meadow with tall grass and distant hills",
        "a cozy living room": "lakeside setting with water and cattails visible",
        "": "lush green field with scattered wildflowers"
      };

      const backgroundSetting = backgroundSettings[background as keyof typeof backgroundSettings] || "lush green field with scattered wildflowers";

      const prompt = `Photo-realistic image of a ${breedText}${colorText} dog, high-quality digital photography, natural lighting, crisp focus throughout entire image. The dog should be the main subject with alert, friendly expression. Realistic natural background in sharp focus - ${backgroundSetting}. Background should be fully detailed and in focus, not blurred or faded. The image should look like a candid photograph taken during a walk or outdoor adventure, with natural colors, realistic lighting, and authentic outdoor environment. Sharp details on both the dog and the background scenery. Natural depth and perspective showing the dog as part of the real environment.`;

      let imageUrl: string;
      let isDemo = false;

      try {
        const response = await openai.images.generate({
          model: "dall-e-3",
          prompt: prompt,
          n: 1,
          size: "1024x1024",
          quality: "hd",
          style: "natural",
        });

        const generatedUrl = response.data?.[0]?.url;
        if (!generatedUrl) {
          throw new Error("No image URL returned");
        }
        imageUrl = generatedUrl;
      } catch (error: any) {
        console.log("OpenAI generation failed, using demo mode:", error.message);

        const demoImages = [
          "https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=1024&h=1024&fit=crop&crop=center",
          "https://images.unsplash.com/photo-1583337130417-3346a1be7dee?w=1024&h=1024&fit=crop&crop=center",
          "https://images.unsplash.com/photo-1561037404-61cd46aa615b?w=1024&h=1024&fit=crop&crop=center",
          "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1024&h=1024&fit=crop&crop=center",
          "https://images.unsplash.com/photo-1552053831-71594a27632d?w=1024&h=1024&fit=crop&crop=center"
        ];

        imageUrl = demoImages[Math.floor(Math.random() * demoImages.length)];
        isDemo = true;
      }

      const generationId = Math.random().toString(36).substr(2, 6).toUpperCase();

      const portrait = await storage.createDogPortrait({
        breed: breedText,
        imageUrl,
        name: randomName,
        generationId,
      });

      res.json({ ...portrait, isDemo });
    } catch (error) {
      console.error("Error generating portrait:", error);
      res.status(500).json({ 
        message: "Failed to generate dog portrait. Please try again." 
      });
    }
  });

  app.get("/api/recent-portraits", async (req, res) => {
    try {
      const limit = parseInt(req.query.limit as string) || 10;
      const portraits = await storage.getRecentPortraits(limit);
      res.json(portraits);
    } catch (error) {
      console.error("Error fetching recent portraits:", error);
      res.status(500).json({ 
        message: "Failed to fetch recent portraits" 
      });
    }
  });

  app.get("/api/portrait/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) {
        return res.status(400).json({ message: "Invalid portrait ID" });
      }

      const portrait = await storage.getDogPortrait(id);
      if (!portrait) {
        return res.status(404).json({ message: "Portrait not found" });
      }

      res.json(portrait);
    } catch (error) {
      console.error("Error fetching portrait:", error);
      res.status(500).json({ 
        message: "Failed to fetch portrait" 
      });
    }
  });

  app.post("/api/email-signup", async (req, res) => {
    try {
      const validatedData = insertEmailSignupSchema.parse(req.body);

      const existingSignup = await storage.getEmailSignup(validatedData.email);
      if (existingSignup) {
        return res.status(400).json({ message: "Email already signed up" });
      }

      const signup = await storage.createEmailSignup(validatedData);
      res.json({ message: "Successfully signed up for picture of the day!", signup });
    } catch (error) {
      if (error instanceof z.ZodError) {
        res.status(400).json({ message: "Invalid email format" });
      } else {
        res.status(500).json({ message: "Failed to sign up" });
      }
    }
  });

  app.get("/api/proxy-image", async (req, res) => {
    try {
      const { url } = req.query;

      if (!url || typeof url !== 'string') {
        return res.status(400).json({ message: "URL parameter is required" });
      }

      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`Failed to fetch image: ${response.status}`);
      }

      const contentType = response.headers.get('content-type') || 'image/jpeg';

      res.setHeader('Content-Type', contentType);
      res.setHeader('Access-Control-Allow-Origin', '*');

      const buffer = await response.arrayBuffer();
      res.send(Buffer.from(buffer));
    } catch (error) {
      console.error("Error proxying image:", error);
      res.status(500).json({ message: "Failed to fetch image" });
    }
  });

  app.post("/api/create-checkout-session", async (req, res) => {
    try {
      if (!process.env.STRIPE_SECRET_KEY?.startsWith('sk_')) {
        return res.status(400).json({ 
          message: "Stripe configuration error. Please update your STRIPE_SECRET_KEY to use a secret key (starts with sk_) instead of a publishable key (pk_)." 
        });
      }

      const session = await stripe.checkout.sessions.create({
        payment_method_types: ['card'],
        line_items: [
          {
            price_data: {
              currency: 'usd',
              product_data: {
                name: 'Pup Portrait Premium',
                description: 'Unlimited portraits, priority processing, exclusive AI models, custom colors & backgrounds',
              },
              unit_amount: 999,
            },
            quantity: 1,
          },
        ],
        mode: 'payment',
        success_url: `${req.headers.origin || 'http://localhost:5000'}/?premium=success`,
        cancel_url: `${req.headers.origin || 'http://localhost:5000'}/?premium=cancelled`,
        metadata: {
          product: 'premium_upgrade',
          description: 'Pup Portrait Premium Features'
        }
      });

      res.json({ 
        sessionId: session.id,
        url: session.url
      });
    } catch (error: any) {
      console.error("Error creating checkout session:", error);
      res.status(500).json({ 
        message: "Stripe configuration error. Please check your API keys. Secret key should start with 'sk_' and publishable key should start with 'pk_'." 
      });
    }
  });

  app.post("/api/stripe-webhook", async (req, res) => {
    const sig = req.headers['stripe-signature'];
    let event;

    try {
      event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET || '');
    } catch (err: any) {
      console.log(`Webhook signature verification failed.`, err.message);
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object;
      console.log('Payment successful for session:', session.id);
    }

    res.json({ received: true });
  });

  const httpServer = createServer(app);
  return httpServer;
}

