import { users, dogPortraits, emailSignups, type User, type InsertUser, type DogPortrait, type InsertDogPortrait, type EmailSignup, type InsertEmailSignup } from "@shared/schema";

export interface IStorage {
  getUser(id: number): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;
  createDogPortrait(portrait: InsertDogPortrait): Promise<DogPortrait>;
  getDogPortrait(id: number): Promise<DogPortrait | undefined>;
  getRecentPortraits(limit: number): Promise<DogPortrait[]>;
  createEmailSignup(signup: InsertEmailSignup): Promise<EmailSignup>;
  getEmailSignup(email: string): Promise<EmailSignup | undefined>;
}

export class MemStorage implements IStorage {
  private users: Map<number, User>;
  private dogPortraits: Map<number, DogPortrait>;
  private emailSignups: Map<number, EmailSignup>;
  private currentUserId: number;
  private currentPortraitId: number;
  private currentEmailSignupId: number;

  constructor() {
    this.users = new Map();
    this.dogPortraits = new Map();
    this.emailSignups = new Map();
    this.currentUserId = 1;
    this.currentPortraitId = 1;
    this.currentEmailSignupId = 1;
  }

  async getUser(id: number): Promise<User | undefined> {
    return this.users.get(id);
  }

  async getUserByUsername(username: string): Promise<User | undefined> {
    return Array.from(this.users.values()).find(
      (user) => user.username === username,
    );
  }

  async createUser(insertUser: InsertUser): Promise<User> {
    const id = this.currentUserId++;
    const user: User = { ...insertUser, id };
    this.users.set(id, user);
    return user;
  }

  async createDogPortrait(insertPortrait: InsertDogPortrait): Promise<DogPortrait> {
    const id = this.currentPortraitId++;
    const portrait: DogPortrait = { 
      ...insertPortrait, 
      id, 
      createdAt: new Date() 
    };
    this.dogPortraits.set(id, portrait);
    return portrait;
  }

  async getDogPortrait(id: number): Promise<DogPortrait | undefined> {
    return this.dogPortraits.get(id);
  }

  async getRecentPortraits(limit: number): Promise<DogPortrait[]> {
    const portraits = Array.from(this.dogPortraits.values());
    return portraits
      .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())
      .slice(0, limit);
  }

  async createEmailSignup(insertSignup: InsertEmailSignup): Promise<EmailSignup> {
    const id = this.currentEmailSignupId++;
    const signup: EmailSignup = { 
      ...insertSignup, 
      id, 
      signupDate: new Date(),
      isActive: true
    };
    this.emailSignups.set(id, signup);
    return signup;
  }

  async getEmailSignup(email: string): Promise<EmailSignup | undefined> {
    return Array.from(this.emailSignups.values()).find(
      (signup) => signup.email === email,
    );
  }
}

export const storage = new MemStorage();

