import { pgTable, text, serial, integer, boolean, timestamp, varchar } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  username: text("username").notNull().unique(),
  password: text("password").notNull(),
});

export const dogPortraits = pgTable("dog_portraits", {
  id: serial("id").primaryKey(),
  breed: text("breed").notNull(),
  imageUrl: text("image_url").notNull(),
  name: text("name").notNull(),
  generationId: text("generation_id").notNull(),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const emailSignups = pgTable("email_signups", {
  id: serial("id").primaryKey(),
  email: varchar("email", { length: 255 }).notNull().unique(),
  signupDate: timestamp("signup_date").defaultNow().notNull(),
  isActive: boolean("is_active").default(true).notNull(),
});

export const insertUserSchema = createInsertSchema(users).pick({
  username: true,
  password: true,
});

export const insertDogPortraitSchema = createInsertSchema(dogPortraits).pick({
  breed: true,
  imageUrl: true,
  name: true,
  generationId: true,
});

export const insertEmailSignupSchema = createInsertSchema(emailSignups).pick({
  email: true,
});

export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;
export type DogPortrait = typeof dogPortraits.$inferSelect;
export type InsertDogPortrait = z.infer<typeof insertDogPortraitSchema>;
export type EmailSignup = typeof emailSignups.$inferSelect;
export type InsertEmailSignup = z.infer<typeof insertEmailSignupSchema>;

